const selectedActivity = ref(null);       
const isBudgetsloading = ref(false);

const openPlans      = ref(new Set());
const openActivities = ref(new Set());

const selectedNode = ref(null);
const selectedProgress = ref(null)
const activity_name            = ref('');
const start_date               = ref('');
const end_date                 = ref('');


const clearForm = ()=>{
  progressResources.value = []
  selectedProgress.value = ''
}

const formatDate = (dateStr) => {
  if (!dateStr) return '';
  const [year, month, day] = dateStr.split('-').map(Number);
  const d = new Date(year, month - 1, day);
  const dayName = d.toLocaleDateString('en-US', { weekday: 'short' });
  return `${dayName} ${month}/${day}/${String(year).slice(-2)}`;
};

const axiosInstance = axios.create({ baseURL: process.env.VUE_APP_API_BASE_URL });


const toggleActivityOpen = (activityId) => {
  const next = new Set(openActivities.value);
  if (next.has(activityId)) next.delete(activityId);
  else next.add(activityId);
  openActivities.value = next;
};

const selectPlan = (plan) => {
  selectedPlan.value = plan;
  selectedNode.value = { id: plan.id, type: 'plan', data: plan };
  
  // Auto-toggle open/close when selecting
  const next = new Set(openPlans.value);
  if (next.has(plan.id)) {
    next.delete(plan.id);
  } else {
    next.add(plan.id);
    if (!plan.activities) getWorkPlanActivities(plan);
  }
  openPlans.value = next;
};

const selectActivity = (plan, activity) => {
  getProgressList(activity.id)
  selectedPlan.value = plan;
  selectedActivity.value = activity;
  selectedNode.value = { id: activity.id, type: 'activity', data: activity, parentPlan: plan };
  const next = new Set(openActivities.value);
  if (next.has(activity.id)) {
    next.delete(activity.id);
  } else {
    next.add(activity.id);
  }
  openActivities.value = next;
};



const getPlanDateRange = (plan) => {
  const activities = plan?.activities;
  if (!activities || activities.length === 0) return { start: 'N/A', end: 'N/A' };
  const sorted = [...activities].sort((a, b) => new Date(a.start_date) - new Date(b.start_date));
  return {
    start: sorted[0]?.start_date || 'N/A',
    end:   sorted[sorted.length - 1]?.end_date || 'N/A',
  };
};

const getWorkPlan = async (showLoading = true) => {
  if (showLoading) { loading_spinner.value = true; loadingPlans.value = true; }
  try {
    const response = await axiosInstance.get(`work-plans?budget_id=${selectedBudget.value.id}`);
    const prev = workPlans.value;
    workPlans.value = response.data.map(wp => {
      const old = prev.find(p => p.id === wp.id);
      return old?.activities ? { ...wp, activities: old.activities } : wp;
    });

    await Promise.all(workPlans.value.map(plan => getWorkPlanActivities(plan)));

    openPlans.value = new Set(workPlans.value.map(p => p.id));

    const allActivityIds = new Set();
    workPlans.value.forEach(plan => {
      (plan.activities || []).forEach(act => allActivityIds.add(act.id));
    });
    openActivities.value = allActivityIds;

    if (selectedNode.value?.type === 'plan') {
      const fresh = workPlans.value.find(p => p.id === selectedNode.value.id);
      if (fresh) selectedNode.value = { ...selectedNode.value, data: fresh };
    }
  } catch (error) {
    showError(error.message);
  } finally {
    if (showLoading) { loading_spinner.value = false; loadingPlans.value = false; }
  }
};

const getWorkPlanActivities = async (plan) => {
  loadingActivitiesFor.value = plan.id;
  try {
    const response = await axiosInstance.get(`work-plan-activities?work_plan_id=${plan.id}`);
    plan.activities = response.data;
    if (selectedNode.value?.type === 'activity' && selectedNode.value.parentPlan?.id === plan.id) {
      const updatedAct = plan.activities.find(a => a.id === selectedNode.value.id);
      if (updatedAct) selectedNode.value = { ...selectedNode.value, data: updatedAct };
    }
    if (selectedNode.value?.type === 'plan' && selectedNode.value.id === plan.id) {
      selectedNode.value = { ...selectedNode.value, data: plan };
    }
  } catch (error) {
    showError(error.message);
  } finally {
    loadingActivitiesFor.value = null;
  }
};


const getProjects = async () => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get(`projects?company_id=6&status=active`);
    projects.value = response.data
      .filter(item => item.contracted === 'YES')
      .filter(item => item.status === 'active');
  } catch (error) {
    showError(error.message);
  } finally {
    loading_spinner.value = false;
  }
};

const getBudgets = async () => {
  isBudgetsloading.value = true;
  try {
    const response = await axiosInstance.get(`get-budgets?project_id=${selectedProject.value.id}`);
    budgets.value = response.data.filter(b => b.status === "closed");
  } catch (error) {
    showError(error.message);
  } finally {
    isBudgetsloading.value = false;
  }
};


const units = ref([])
const unit= ref('')
const getUnits = async()=>{
  const response  = await axiosInstance.get('units')
  units.value = response.data
}


const toggleProject = async (project) => {
  selectedProject.value  = project;
  selectedBudget.value   = null;
  selectedBudgetId.value = null;
  selectedPlan.value     = null;
  selectedActivity.value = null;
  selectedNode.value     = null;
  workPlans.value        = [];
  openPlans.value        = new Set();
  openActivities.value   = new Set();
  await getBudgets();
};

const fillBudget = (budget) => {
  if (selectedBudgetId.value === budget.id) {
    selectedBudget.value   = null;
    selectedBudgetId.value = null;
    selectedPlan.value     = null;
    selectedActivity.value = null;
    selectedNode.value     = null;
    workPlans.value        = [];
    openPlans.value        = new Set();
    openActivities.value   = new Set();
    return;
  }
  selectedBudget.value   = budget;
  selectedBudgetId.value = budget.id;
  selectedPlan.value     = null;
  selectedActivity.value = null;
  selectedNode.value     = null;
  workPlans.value        = [];
  openPlans.value        = new Set();
  openActivities.value   = new Set();
  getWorkPlan();
};





const progressColor = ref('')
const activities = ref([])
const activity = ref([])
const qty_achieved  = ref('');
const achieved_date = ref('');
const description = ref('')
const externalList = ref([])
const ext = ref({ name: '', unit: null, quantity: '' })

const addExternal = () => {
  const { name, unit, quantity } = ext.value;
  if (!name.trim() || !unit || !(Number(quantity) > 0)) return showError('Fill name, unit and quantity');
  externalList.value.push({ name: name.trim(), unit: unit.short_name,unit_id :unit.id, quantity });
  ext.value = { name: '', unit: null, quantity: '' };
};

const resetResources = () => {
  activity.value = [];
  externalList.value = [];
  ext.value = { name: '', unit: null, quantity: '' };
  qty_achieved.value = '';
  achieved_date.value = '';
};
const removeListResource = (r) => {
  activity.value = activity.value.filter(x => x.id !== r.id);
};

const closeActivityModal = () => { activity_name.value = ''; start_date.value = ''; end_date.value = ''; resetResources(); };

const openEditActivityModal = (act) => {
  console.log(act)
  resetResources();
  activity_name.value  = act.name;
  start_date.value     = act.start_date;
  end_date.value       = act.end_date;
  selectedActivity.value = act;
  activities.value = act.lines || [];
};


const submitProgress = async () => {
  if (!selectedActivity.value) return showError('No activity selected');
  if (!(Number(qty_achieved.value) > 0)) return showError('Enter the quantity achieved');
  if (!achieved_date.value) return showError('Select the achieved date');

  const plannedResources = (activity.value || []).filter(Boolean);
  const unplanned = externalList.value;

  if (plannedResources.some(r => !(Number(r.quantity) > 0)) || unplanned.some(r => !(Number(r.quantity) > 0))) {
    return showError('Every resource needs a quantity greater than 0');
  }

  const payload = {
    work_plan_id: selectedPlan.value?.id,
    work_plan_activity_id: selectedActivity.value.id,
    quantity_achieved: Number(qty_achieved.value),
    achieved_date: achieved_date.value,
    description : description.value,
    issuer_id : JSON.parse(localStorage.getItem("user")).id,
    planned_resources: plannedResources.map(r => ({
      line_id: r.id,
      name: r.name,
      unit: r.unit,
      unit_id : r.unit_id,
      quantity: Number(r.quantity),
    })),
    unplanned_resources: unplanned.map(r => ({
      name: r.name,
      unit: r.unit,
      unit_id : r.unit_id,
      quantity: Number(r.quantity),
    })),
  };

  updating.value = true;
  try {
    // console.log(payload)
    const response = await axiosInstance.post('store-work-achievement', payload);
    showMessage(response.data?.message || 'Progress saved');
    document.getElementById('close_edit_activity')?.click();
    await getWorkPlan(false);
  } catch (error) {
    showError(error.response?.data?.message || error.message);
  } finally {
    updating.value = false;
  }
};

const progressList = ref([])
const getProgressList = async (id)=>{
  loading.value = true
  try{
   const response = await axiosInstance.get(`archived-work-plan-activities?activity_id=${id}`)
   progressList.value = response.data
  }catch(error){
    console.log(error)
    showError(error.message
    )
  }finally{
   loading.value = false
  }
}

const loading_resources = ref(false)
const progressResources = ref([])
const getProgressResources = async (id)=>{
  loading_resources.value = true
  try{
   const response = await axiosInstance.get(`work-plan-activities-resources?parent_id=${id}`)
   progressResources.value = response.data
  }catch(error){
    console.log(error)
    showError(error.message
    )
  }finally{
  loading_resources.value = false
  }
}



onMounted(() => {
  getProjects();
  getUnits()
  const offcanvasElement = document.getElementById('offcanvasWithBothOptions');
  if (offcanvasElement) {
    const offcanvas = new bootstrap.Offcanvas(offcanvasElement);
    offcanvas.show();
  }
});







</script>

